args.command:
/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict'

for (const [slug, title, description, activity] of [
  ['acme', 'Acme Storefront', 'Commerce storefront and checkout.', 'Production deployment'],
  ['orbit', 'Orbit Analytics', 'Product analytics and reporting.', 'Report published'],
]) {
  const url = "'`http://localhost:3123/projects/${slug}`
  const prefetch = await fetch(url, { headers: { RSC: '"'1', 'Next-Router-Prefetch': '2' } }).then((response) => response.text())
  assert.ok(prefetch.includes(title), "'`${slug}: title missing from prefetch`)
  assert.ok(prefetch.includes('"'Loading project details...'), "'`${slug}: details fallback missing`)
  assert.ok(!prefetch.includes(description) && !prefetch.includes(activity), `${slug}: details included in prefetch`)
  const navigation = await fetch(url, { headers: { RSC: '"'1' } }).then((response) => response.text())
  assert.ok(navigation.includes(title) && navigation.includes(description) && navigation.includes(activity), "'`${slug}: navigation content missing`)
  console.log(`${slug}: title prefetched, details deferred and present on navigation`)
}
NODE'

